     1	<#
     2	  Re-runs any managed job that has not succeeded today.
     3	
     4	  Registered as the 'KeystoneOS-Reconcile' task (logon +5m, then hourly 07:00-19:00).
     5	  Cheap and idempotent: the common case is a few file reads and no work at all.
     6	
     7	  Semantics are deliberately today-only. A morning cadence from three days ago has no
     8	  value if replayed now, and the jobs that DO matter after an outage (the backup) are
     9	  snapshots rather than per-day increments - running today's covers the gap.
    10	
    11	  Usage:
    12	    .\keystone-reconcile.ps1            # reconcile
    13	    .\keystone-reconcile.ps1 -DryRun    # report decisions, change nothing
    14	    .\keystone-reconcile.ps1 -Json      # machine-readable decision table
    15	#>
    16	param(
    17	    [switch]$DryRun,
    18	    [switch]$Json,
    19	    [string]$RegistryPath,
    20	    [string]$LedgerPath
    21	)
    22	
    23	$ErrorActionPreference = "Stop"
    24	. (Join-Path $PSScriptRoot "run-ledger.ps1")
    25	
    26	$now = Get-Date
    27	$decisions = @()
    28	
    29	function New-Decision {
    30	    param([string]$Id, [string]$Action, [string]$Reason)
    31	    [pscustomobject]@{ job = $Id; action = $Action; reason = $Reason; at = $now.ToString("o") }
    32	}
    33	
    34	function Add-ErrorLogLine {
    35	    <# Surfaced at every session start per CLAUDE.md. Deduped per day. #>
    36	    param([Parameter(Mandatory)][string]$Message)
    37	    $path = Join-Path $HOME ".claude/global-memory/transcripts/.errors.log"
    38	    $dir = Split-Path -Parent $path
    39	    if (-not (Test-Path -LiteralPath $dir)) { return }
    40	    $line = "$($now.ToString('yyyy-MM-dd HH:mm')) $Message"
    41	    $key = "$($now.ToString('yyyy-MM-dd'))*$Message"
    42	    if (Test-Path -LiteralPath $path) {
    43	        $existing = Get-Content -LiteralPath $path -ErrorAction SilentlyContinue
    44	        if ($existing | Where-Object { $_ -like $key }) { return }
    45	    }
    46	    Add-Content -LiteralPath $path -Value $line
    47	}
    48	
    49	foreach ($job in (Get-JobRegistry -Path $RegistryPath)) {
    50	
    51	    # Monitoring that applies whoever ran the job: a briefing that "succeeded" while its
    52	    # Outlook session was dead still went out empty. Make that visible before tomorrow's.
    53	    if ($job.PSObject.Properties['authWarnProbe'] -and $job.authWarnProbe) {
    54	        if (Test-Probe -Probe $job.authWarnProbe -Date $now) {
    55	            if (Test-WarningSuperseded -Probe $job.authWarnProbe -Date $now) {
    56	                $decisions += New-Decision -Id $job.id -Action "skip" -Reason "auth warning superseded (re-authenticated since)"
    57	            } else {
    58	                if (-not $DryRun) { Add-ErrorLogLine -Message $job.authWarnProbe.message }
    59	                $decisions += New-Decision -Id $job.id -Action "warn" -Reason $job.authWarnProbe.message
    60	            }
    61	        }
    62	    }
    63	
    64	    $reconcileEnabled = $job.PSObject.Properties['reconcile'] -and $job.reconcile
    65	    if (-not $reconcileEnabled) {
    66	        $decisions += New-Decision -Id $job.id -Action "skip" -Reason "monitor-only (reconcile=false)"
    67	        continue
    68	    }
    69	    if (-not (Test-ScheduledOn -Job $job -Date $now)) {
    70	        $decisions += New-Decision -Id $job.id -Action "skip" -Reason "not scheduled today"
    71	        continue
    72	    }
    73	
    74	    $due = (Get-ScheduledDateTime -Job $job -Date $now).AddMinutes([int]$job.graceMinutes)
    75	    if ($now -lt $due) {
    76	        $decisions += New-Decision -Id $job.id -Action "skip" -Reason "not due until $($due.ToString('HH:mm'))"
    77	        continue
    78	    }
    79	    if (Test-JobCompleteOn -Job $job -Date $now -LedgerPath $LedgerPath) {
    80	        $decisions += New-Decision -Id $job.id -Action "skip" -Reason "already succeeded today"
    81	        continue
    82	    }
    83	    if (-not (Test-InMakeupWindow -Job $job -Now $now)) {
    84	        $decisions += New-Decision -Id $job.id -Action "skip" -Reason "outside make-up window"
    85	        continue
    86	    }
    87	
    88	    $failures = Get-LedgerFailureCountOn -Id $job.id -Date $now -Path $LedgerPath
    89	    if ($failures -ge [int]$job.maxAttemptsPerDay) {
    90	        $decisions += New-Decision -Id $job.id -Action "give-up" -Reason "$failures failed attempts today (cap $($job.maxAttemptsPerDay))"
    91	        if (-not $DryRun) { Add-ErrorLogLine -Message "$($job.id): failed $failures times today, giving up. See outputs\jobs\." }
    92	        continue
    93	    }
    94	    if (Test-JobLockBusy -Id $job.id) {
    95	        $decisions += New-Decision -Id $job.id -Action "skip" -Reason "already running"
    96	        continue
    97	    }
    98	
    99	    $decisions += New-Decision -Id $job.id -Action "make-up" -Reason "no success recorded for today"
   100	    if ($DryRun) { continue }
   101	
   102	    $runJob = Join-Path $PSScriptRoot "run-job.ps1"
   103	    & $runJob -Job $job.id -Trigger "reconcile" -MadeUp -RegistryPath $RegistryPath -LedgerPath $LedgerPath
   104	}
   105	
   106	if ($Json) {
   107	    $decisions | ConvertTo-Json -Depth 5
   108	} else {
   109	    Write-Host "== KeystoneOS reconcile ($($now.ToString('yyyy-MM-dd HH:mm')))$(if ($DryRun) { ' [dry run]' })"
   110	    foreach ($d in $decisions) {
   111	        $tag = switch ($d.action) {
   112	            'make-up' { 'MAKE-UP' }
   113	            'give-up' { 'GIVE-UP' }
   114	            'warn'    { 'WARN   ' }
   115	            default   { 'ok     ' }
   116	        }
   117	        Write-Host ("  {0} {1,-18} {2}" -f $tag, $d.job, $d.reason)
   118	    }
   119	    if (-not ($decisions | Where-Object { $_.action -in @('make-up', 'give-up', 'warn') })) {
   120	        Write-Host "  all managed jobs are current."
   121	    }
   122	}
#####
     1	# Shared helpers for the KeystoneOS run ledger and job registry.
     2	# Dot-source this file; it defines functions and does no work on its own.
     3	#
     4	# The ledger answers one question nothing else could answer: "did this job actually
     5	# succeed today?" Before it existed, the scheduler's own history was the only record,
     6	# and that records "the process exited", not "the work happened".
     7	
     8	Set-StrictMode -Version Latest
     9	
    10	function Get-KeystoneRoot {
    11	    (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot "..")).Path
    12	}
    13	
    14	function Get-KeystoneDevRoot {
    15	    # DEV is the parent of the KeystoneOS repo.
    16	    (Resolve-Path -LiteralPath (Join-Path (Get-KeystoneRoot) "..")).Path
    17	}
    18	
    19	function Expand-JobToken {
    20	    param(
    21	        [Parameter(Mandatory)][AllowEmptyString()][string]$Value,
    22	        [datetime]$Date = (Get-Date)
    23	    )
    24	    $out = $Value
    25	    $out = $out.Replace("{REPO}", (Get-KeystoneRoot))
    26	    $out = $out.Replace("{DEV}", (Get-KeystoneDevRoot))
    27	    $out = $out.Replace("{USERPROFILE}", $HOME)
    28	    $out = $out.Replace("{DATE}", $Date.ToString("yyyy-MM-dd"))
    29	    $out
    30	}
    31	
    32	function Get-JobRegistry {
    33	    param([string]$Path)
    34	    if (-not $Path) { $Path = Join-Path (Get-KeystoneRoot) "data/jobs.json" }
    35	    if (-not (Test-Path -LiteralPath $Path)) { throw "Job registry not found: $Path" }
    36	    $raw = Get-Content -Raw -LiteralPath $Path
    37	    ($raw | ConvertFrom-Json).jobs
    38	}
    39	
    40	function Get-JobDefinition {
    41	    param(
    42	        [Parameter(Mandatory)][string]$Id,
    43	        [string]$RegistryPath
    44	    )
    45	    $job = Get-JobRegistry -Path $RegistryPath | Where-Object { $_.id -eq $Id }
    46	    if (-not $job) { throw "Unknown job id '$Id'. Check data\jobs.json." }
    47	    $job
    48	}
    49	
    50	function Get-LedgerPath {
    51	    param([string]$Root)
    52	    if (-not $Root) { $Root = Get-KeystoneRoot }
    53	    Join-Path $Root "outputs/run-ledger.json"
    54	}
    55	
    56	# --- locking -----------------------------------------------------------------
    57	# A named mutex, not a PID file: when the holding process is killed outright (which
    58	# is exactly what a Restart Manager shutdown does), Windows marks the mutex abandoned
    59	# and the next waiter acquires it cleanly. A PID file would be left behind as a stale
    60	# lock and would need heuristics to break.
    61	
    62	function New-KeystoneMutex {
    63	    param([Parameter(Mandatory)][string]$Name)
    64	    $safe = $Name -replace '[^A-Za-z0-9_-]', '_'
    65	    try {
    66	        [System.Threading.Mutex]::new($false, "Global\KeystoneOS-$safe")
    67	    } catch [System.UnauthorizedAccessException] {
    68	        # Global namespace can be denied by policy; a session-local mutex still gives
    69	        # mutual exclusion between the scheduled task and the reconciler.
    70	        [System.Threading.Mutex]::new($false, "Local\KeystoneOS-$safe")
    71	    }
    72	}
    73	
    74	function Invoke-WithMutex {
    75	    param(
    76	        [Parameter(Mandatory)][string]$Name,
    77	        [Parameter(Mandatory)][scriptblock]$Body,
    78	        [int]$TimeoutMs = 0,
    79	        [switch]$SkipIfBusy
    80	    )
    81	    $mutex = New-KeystoneMutex -Name $Name
    82	    $held = $false
    83	    try {
    84	        try {
    85	            $held = $mutex.WaitOne($TimeoutMs)
    86	        } catch [System.Threading.AbandonedMutexException] {
    87	            # Previous holder died without releasing. We now own it.
    88	            $held = $true
    89	        }
    90	        if (-not $held) {
    91	            if ($SkipIfBusy) { return $null }
    92	            throw "Could not acquire lock '$Name' within ${TimeoutMs}ms."
    93	        }
    94	        & $Body
    95	    }
    96	    finally {
    97	        if ($held) { try { $mutex.ReleaseMutex() } catch { } }
    98	        $mutex.Dispose()
    99	    }
   100	}
   101	
   102	function Test-JobLockBusy {
   103	    param([Parameter(Mandatory)][string]$Id)
   104	    $mutex = New-KeystoneMutex -Name "job-$Id"
   105	    try {
   106	        $got = $false
   107	        try { $got = $mutex.WaitOne(0) }
   108	        catch [System.Threading.AbandonedMutexException] { $got = $true }
   109	        if ($got) { try { $mutex.ReleaseMutex() } catch { } }
   110	        -not $got
   111	    }
   112	    finally { $mutex.Dispose() }
   113	}
   114	
   115	# --- ledger read/write -------------------------------------------------------
   116	
   117	function Read-RunLedger {
   118	    param([string]$Path)
   119	    if (-not $Path) { $Path = Get-LedgerPath }
   120	    if (-not (Test-Path -LiteralPath $Path)) {
   121	        return [pscustomobject]@{ version = 1; jobs = [pscustomobject]@{} }
   122	    }
   123	    try {
   124	        $raw = Get-Content -Raw -LiteralPath $Path
   125	        if (-not $raw -or -not $raw.Trim()) {
   126	            return [pscustomobject]@{ version = 1; jobs = [pscustomobject]@{} }
   127	        }
   128	        $raw | ConvertFrom-Json
   129	    } catch {
   130	        # A truncated ledger (killed mid-write) must not take the whole system down.
   131	        # Preserve the damaged file for inspection and start clean.
   132	        $bak = "$Path.corrupt-$((Get-Date).ToString('yyyyMMddHHmmss'))"
   133	        try { Move-Item -LiteralPath $Path -Destination $bak -Force } catch { }
   134	        [pscustomobject]@{ version = 1; jobs = [pscustomobject]@{} }
   135	    }
   136	}
   137	
   138	function Get-JobEntries {
   139	    param(
   140	        [Parameter(Mandatory)]$Ledger,
   141	        [Parameter(Mandatory)][string]$Id
   142	    )
   143	    if (-not $Ledger.PSObject.Properties['jobs']) { return @() }
   144	    $jobs = $Ledger.jobs
   145	    if (-not $jobs -or -not $jobs.PSObject.Properties[$Id]) { return @() }
   146	    @($jobs.$Id)
   147	}
   148	
   149	function Add-LedgerEntry {
   150	    param(
   151	        [Parameter(Mandatory)][string]$Id,
   152	        [Parameter(Mandatory)][string]$Status,
   153	        [int]$ExitCode = 0,
   154	        [datetime]$StartedAt = (Get-Date),
   155	        [datetime]$FinishedAt = (Get-Date),
   156	        [string]$Trigger = "scheduled",
   157	        [switch]$MadeUp,
   158	        [string]$Note,
   159	        [string]$Path,
   160	        [int]$KeepPerJob = 60
   161	    )
   162	    if (-not $Path) { $Path = Get-LedgerPath }
   163	    $dir = Split-Path -Parent $Path
   164	    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
   165	
   166	    $entry = [ordered]@{
   167	        date        = $StartedAt.ToString("yyyy-MM-dd")
   168	        status      = $Status
   169	        exitCode    = $ExitCode
   170	        startedAt   = $StartedAt.ToString("o")
   171	        finishedAt  = $FinishedAt.ToString("o")
   172	        durationSec = [int]([math]::Round(($FinishedAt - $StartedAt).TotalSeconds))
   173	        trigger     = $Trigger
   174	        madeUp      = [bool]$MadeUp
   175	    }
   176	    if ($Note) { $entry.note = $Note }
   177	
   178	    Invoke-WithMutex -Name "run-ledger" -TimeoutMs 15000 -Body {
   179	        $ledger = Read-RunLedger -Path $Path
   180	        if (-not $ledger.PSObject.Properties['jobs'] -or -not $ledger.jobs) {
   181	            $ledger | Add-Member -NotePropertyName jobs -NotePropertyValue ([pscustomobject]@{}) -Force
   182	        }
   183	        $existing = @(Get-JobEntries -Ledger $ledger -Id $Id)
   184	        $updated = @([pscustomobject]$entry) + $existing
   185	        if ($updated.Count -gt $KeepPerJob) { $updated = $updated[0..($KeepPerJob - 1)] }
   186	        $ledger.jobs | Add-Member -NotePropertyName $Id -NotePropertyValue $updated -Force
   187	
   188	        $tmp = "$Path.tmp"
   189	        ($ledger | ConvertTo-Json -Depth 10) | Set-Content -LiteralPath $tmp -Encoding UTF8
   190	        Move-Item -LiteralPath $tmp -Destination $Path -Force
   191	    } | Out-Null
   192	
   193	    [pscustomobject]$entry
   194	}
