   223	function Test-Probe {
   224	    <#
   225	      Evaluates a job's successProbe / authWarnProbe against its own log output.
   226	      Returns $false when the probe cannot be evaluated (missing file), never throws —
   227	      an unevaluable probe must not be read as success.
   228	    #>
   229	    param(
   230	        $Probe,
   231	        [datetime]$Date = (Get-Date)
   232	    )
   233	    if (-not $Probe) { return $false }
   234	    try {
   235	        $path = Expand-JobToken -Value $Probe.path -Date $Date
   236	        if (-not (Test-Path -LiteralPath $path)) { return $false }
   237	
   238	        switch ($Probe.kind) {
   239	            'fileModifiedToday' {
   240	                $item = Get-Item -LiteralPath $path
   241	                return ($item.LastWriteTime.Date -eq $Date.Date)
   242	            }
   243	            'fileContains' {
   244	                $pattern = Expand-JobToken -Value $Probe.pattern -Date $Date
   245	                return [bool](Select-String -LiteralPath $path -Pattern $pattern -Quiet)
   246	            }
   247	            default { return $false }
   248	        }
   249	    } catch {
   250	        return $false
   251	    }
   252	}
   253	
   254	function Get-NewestWriteTime {
   255	    <#
   256	      Newest LastWriteTime for a file, or for the top-level files of a directory.
   257	      Directory form is deliberate: browser profiles relocate individual files
   258	      between Chrome versions (Cookies moved to Network\Cookies), so pinning a
   259	      single filename is a silent breakage waiting to happen.
   260	    #>
   261	    param([Parameter(Mandatory)][string]$Path)
   262	    if (-not (Test-Path -LiteralPath $Path)) { return $null }
   263	    $item = Get-Item -LiteralPath $Path
   264	    if ($item.PSIsContainer) {
   265	        $files = @(Get-ChildItem -LiteralPath $Path -File -ErrorAction SilentlyContinue)
   266	        if (-not $files) { return $null }
   267	        return ($files | Measure-Object LastWriteTime -Maximum).Maximum
   268	    }
   269	    $item.LastWriteTime
   270	}
   271	
   272	function Test-WarningSuperseded {
   273	    <#
   274	      True when the condition a warning probe matched has since been repaired.
   275	
   276	      A warning probe matches a line written earlier today. Once the underlying
   277	      problem is fixed the line is still there, so the warning would keep firing
   278	      for the rest of the day. 'resolvedIfNewer' names something whose mtime moves
   279	      when the fix happens (a re-authenticated browser profile); newer than the log
   280	      that carried the complaint means the complaint is stale.
   281	    #>
   282	    param(
   283	        $Probe,
   284	        [datetime]$Date = (Get-Date)
   285	    )
   286	    if (-not $Probe) { return $false }
   287	    if (-not $Probe.PSObject.Properties['resolvedIfNewer'] -or -not $Probe.resolvedIfNewer) { return $false }
   288	    try {
   289	        $sourceTime = Get-NewestWriteTime -Path (Expand-JobToken -Value $Probe.path -Date $Date)
   290	        $fixTime = Get-NewestWriteTime -Path (Expand-JobToken -Value $Probe.resolvedIfNewer -Date $Date)
   291	        if ($null -eq $sourceTime -or $null -eq $fixTime) { return $false }
   292	        return ($fixTime -gt $sourceTime)
   293	    } catch {
   294	        return $false
   295	    }
   296	}
