function Invoke-AgySync {
    $agyScript = Join-Path $Root "scripts/agy-sync.ps1"
    if (-not (Test-Path -LiteralPath $agyScript)) { Write-Host "agy-sync bridge unavailable; skipped."; return $null }
    . $agyScript
    Show-Section "agy Memory Bridge Sync"
    $result = Invoke-AgySyncCore -KeystoneRoot $Root -OutputRoot $AgyDir -DryRun:$DryRun

    Write-Host "Digests written: $($result.DigestsWritten.Count)"
    Write-Host "Flushed to compiler: $($result.Flushed.Count)"
    Write-Host "Skipped (no change): $($result.Skipped.Count)"
    if ($result.FlushErrors.Count -gt 0) {
        Write-Host "Flush errors (digest still written, will retry next run): $($result.FlushErrors -join ', ')"
    }
    Write-Host "Conversations dir: $($result.ConversationsDir)"
    Write-Host "Watermark state: $($result.StatePath)"
    return $result
}
